head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup");
};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick1 = function(e) {
    var uri = "wframe_popup_setSrc_modal_remain_WESD-275_(WSQ-4433)_sub.xml";
    var opts = {
        "id": "wframePopup",
        "type": "wframePopup",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "wframePopup",
        "modal": true,
        "title": "wframe popup",
        "foldOnMinimized": true,
        "popupAutoClose": true,
        "windowDragMove": true
    };
    scwin.$w.openPopup(uri, opts);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
